(6265550, 927359, 120129, '<td valign="top">I love the reflections in his eye! Lovely.</td>', 'I love the reflections in his eye! Lovely.', '2011-01-01 00:08:25.000000', NULL, 1),
(6265551, 927104, 110108, '<td valign="top">awesome take, I just wished it was not blurred on the sides</td>', 'awesome take, I just wished it was not blurred on the sides', '2011-01-01 00:10:14.000000', NULL, 1),
(6265555, 927241, 60173, '<td valign="top">It appears you pushed the overall saturation to get some pretty nice colors on your mossy rocks, but unfortunately since you did the whole image the blue in the water was drug along for the ride. The blues are way oversaturated. <br/> <br/>I myself am pretty lazy when it comes to making selections, and don''t do them enough, but this is a case where it would have been a must.</td>', 'It appears you pushed the overall saturation to get some pretty nice colors on your mossy rocks, but unfortunately since you did the whole image the blue in the water was drug along for the ride. The blues are way oversaturated.  I myself am pretty lazy when it comes to making selections, and don''t do them enough, but this is a case where it would have been a must.', '2011-01-01 00:15:19.000000', NULL, 1),
(6265557, 926125, 60173, '<td valign="top">Excellent tones. The bright spot on the wall behind the bottle is great. The wall would have been very boring otherwise. Instead it serves a purpose and draws you in.</td>', 'Excellent tones. The bright spot on the wall behind the bottle is great. The wall would have been very boring otherwise. Instead it serves a purpose and draws you in.', '2011-01-01 00:17:46.000000', NULL, 1),
