(6265993, 924782, 114225, '<td valign="top">Great details in this photo. The line of the stem is really what makes this good to me.</td>', 'Great details in this photo. The line of the stem is really what makes this good to me.', '2011-01-01 09:25:36.000000', NULL, 1),
(6265994, 927229, 114225, '<td valign="top">Great shot. I''m not normally a fan of many horse photos, but this one has real personality.</td>', 'Great shot. I''m not normally a fan of many horse photos, but this one has real personality.', '2011-01-01 09:26:35.000000', NULL, 1),
(6265997, 927195, 114225, '<td valign="top">Great angle for this photo. Not only did you get details of the bird, but also setup context with the background.</td>', 'Great angle for this photo. Not only did you get details of the bird, but also setup context with the background.', '2011-01-01 09:28:02.000000', NULL, 1),
(6265998, 926270, 114225, '<td valign="top">Wonderful emotion you have captured in this image. The black and white was a great choice, as it really helped convey the emotion.</td>', 'Wonderful emotion you have captured in this image. The black and white was a great choice, as it really helped convey the emotion.', '2011-01-01 09:29:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6266005, 926828, 69324, '<td valign="top">Phenomenal.</td>', 'Phenomenal.', '2011-01-01 09:34:33.000000', NULL, 1),
(6266006, 924314, 73942, '<td valign="top">Love the shadows.  You could crop out the upper sky and have a wonderful panoramic print with this.</td>', 'Love the shadows.  You could crop out the upper sky and have a wonderful panoramic print with this.', '2011-01-01 09:34:45.000000', NULL, 1),
(6266007, 927310, 69324, '<td valign="top">Really nice colors, not overdone.</td>', 'Really nice colors, not overdone.', '2011-01-01 09:37:25.000000', NULL, 1),
(6266008, 927145, 73942, '<td valign="top">nice moment captured, I like how the colors are done here</td>', 'nice moment captured, I like how the colors are done here', '2011-01-01 09:38:24.000000', NULL, 1),
(6266009, 926190, 69324, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2011-01-01 09:43:14.000000', NULL, 1),
(6266010, 927460, 12674, '<td valign="top">A wonderful exposure of a winter wonderland! There''s a lot going on here.  You might try moving in closer and isolating a particular section of the falls to simplify the composition and draw more attention to the subject.</td>', 'A wonderful exposure of a winter wonderland! There''s a lot going on here.  You might try moving in closer and isolating a particular section of the falls to simplify the composition and draw more attention to the subject.', '2011-01-01 09:53:02.000000', NULL, 1),
(6266012, 926715, 12674, '<td valign="top">Pretty color and I like the out of focus circles. It''s a bit unclear what your main subject is. If it''s the out of focus ornament, then the one in the top left is a bit distracting because it''s closer and seems like it should be in focus.</td>', 'Pretty color and I like the out of focus circles. It''s a bit unclear what your main subject is. If it''s the out of focus ornament, then the one in the top left is a bit distracting because it''s closer and seems like it should be in focus.', '2011-01-01 10:05:24.000000', NULL, 1),
(6266015, 927296, 12674, '<td valign="top">An interesting and colorful subject. It could be more sharply focused though, so you might try a faster shutter speed, move in closer so you don''t have to crop so much, or use a tripod next time.</td>', 'An interesting and colorful subject. It could be more sharply focused though, so you might try a faster shutter speed, move in closer so you don''t have to crop so much, or use a tripod next time.', '2011-01-01 10:09:55.000000', NULL, 1),
(6266016, 926163, 63398, '<td valign="top">Very nice, but something tells me you''re getting slammed.....8</td>', 'Very nice, but something tells me you''re getting slammed.....8', '2011-01-01 10:10:00.000000', NULL, 1),
(6266018, 927228, 69324, '<td valign="top">Very nice.</td>', 'Very nice.', '2011-01-01 10:11:46.000000', NULL, 1),
(6266019, 926650, 60495, '<td valign="top">Beautiful scene but the processing is way over the top and in my opinion ruins the image, the processing has created halos and has such an unnatural look but does not even work artistically. I would love to see this one redone because I think it has a lot of potential.</td>', 'Beautiful scene but the processing is way over the top and in my opinion ruins the image, the processing has created halos and has such an unnatural look but does not even work artistically. I would love to see this one redone because I think it has a lot of potential.', '2011-01-01 10:15:34.000000', NULL, 1),
(6266020, 927123, 12674, '<td valign="top">Wow, dramatic subject and wonderful color! This is just a minor thing but it would''ve been nice if the vehicle was free and clear of the bottom edge of the window, just by a little, more out there in the open space of the window if you know what I mean. A very nice shot!</td>', 'Wow, dramatic subject and wonderful color! This is just a minor thing but it would''ve been nice if the vehicle was free and clear of the bottom edge of the window, just by a little, more out there in the open space of the window if you know what I mean. A very nice shot!', '2011-01-01 10:16:04.000000', NULL, 1),
(6266021, 927209, 60495, '<td valign="top">I gave this one an 8 but would have probably given it a 10 if it did not appear so over sharpened, it is such a great capture and getting 2 of these guys over a flower is just awesome. Great shot</td>', 'I gave this one an 8 but would have probably given it a 10 if it did not appear so over sharpened, it is such a great capture and getting 2 of these guys over a flower is just awesome. Great shot', '2011-01-01 10:19:00.000000', NULL, 1),
(6266024, 927474, 63398, '<td valign="top">Nice! How fast was she clocked????....7</td>', 'Nice! How fast was she clocked????....7', '2011-01-01 10:21:27.000000', NULL, 1),
(6266026, 924256, 12674, '<td valign="top">Wow, now that''s flower power, nicely done! You probably tried this, but I might''ve cropped some more to reduce or eliminate the white areas in the two corners. They draw a little bit of attention away from the main petunia that''s most in focus.  But love this shot!</td>', 'Wow, now that''s flower power, nicely done! You probably tried this, but I might''ve cropped some more to reduce or eliminate the white areas in the two corners. They draw a little bit of attention away from the main petunia that''s most in focus.  But love this shot!', '2011-01-01 10:21:30.000000', NULL, 1),
(6266027, 926263, 12674, '<td valign="top">A wonderful view, indeed! Nicely composed and exposed.</td>', 'A wonderful view, indeed! Nicely composed and exposed.', '2011-01-01 10:22:22.000000', NULL, 1),
(6266031, 927379, 12674, '<td valign="top">Beautiful shot, nicely composed! The red ribbon/banner really makes it.</td>', 'Beautiful shot, nicely composed! The red ribbon/banner really makes it.', '2011-01-01 10:24:38.000000', NULL, 1),
(6266051, 927108, 60495, '<td valign="top">Awesome shot, really well captured and processed. My favorite for the challenge. 10</td>', 'Awesome shot, really well captured and processed. My favorite for the challenge. 10', '2011-01-01 10:47:06.000000', NULL, 1),
(6266060, 927410, 60495, '<td valign="top">I wish I could see these simple shots as well as you have captured this. There is nothing special about the shot yet it is so compelling and interesting and the DOF is perfect. Nicely done!</td>', 'I wish I could see these simple shots as well as you have captured this. There is nothing special about the shot yet it is so compelling and interesting and the DOF is perfect. Nicely done!', '2011-01-01 10:53:38.000000', NULL, 1),
