(6266073, 926263, 123833, '<td valign="top">Top photo - is this Lake Geneva?</td>', 'Top photo - is this Lake Geneva?', '2011-01-01 11:21:48.000000', NULL, 1),
(6266075, 927460, 87808, '<td valign="top">Had to stop and comment on this on and explain why I gave it just a 6.  This is a gorgeous, not seen very often shot. For me though, it is all one colour.  I know that sounds odd, but the tone of grey is consistent all the way through this. It is rather a flat shot.  It may have been improved slightly with some dodge and burn, a little curves, just to get some highlights and shadows in it, it needs some sparkles in the snow, the snow all looks grey, you have an amazing shot here but definition would have helped it.</td>', 'Had to stop and comment on this on and explain why I gave it just a 6.  This is a gorgeous, not seen very often shot. For me though, it is all one colour.  I know that sounds odd, but the tone of grey is consistent all the way through this. It is rather a flat shot.  It may have been improved slightly with some dodge and burn, a little curves, just to get some highlights and shadows in it, it needs some sparkles in the snow, the snow all looks grey, you have an amazing shot here but definition would have helped it.', '2011-01-01 11:23:27.000000', NULL, 1),
(6266077, 927227, 87808, '<td valign="top">I love the simplicity of this shot, the darks to the left make is excellent.  8</td>', 'I love the simplicity of this shot, the darks to the left make is excellent.  8', '2011-01-01 11:25:08.000000', NULL, 1),
