(6274584, 926263, 30982, '<td valign="top">A pleasing composition to my eye.</td>', 'A pleasing composition to my eye.', '2011-01-07 00:57:25.000000', NULL, 1),
(6274585, 927148, 30982, '<td valign="top">I spy Catalina.</td>', 'I spy Catalina.', '2011-01-07 00:57:52.000000', NULL, 1),
