(6275184, 924314, 59796, '<td valign="top">Beautiful composition, warm hues and wonderful convergence in the lines of the trees and shadows. Nicely done.</td>', 'Beautiful composition, warm hues and wonderful convergence in the lines of the trees and shadows. Nicely done.', '2011-01-07 16:59:21.000000', NULL, 1),
(6275186, 927447, 30454, '<td valign="top">Great Depth in the photo, the Owl is looking right into the camera, great capture. Good luck.</td>', 'Great Depth in the photo, the Owl is looking right into the camera, great capture. Good luck.', '2011-01-07 17:00:01.000000', NULL, 1),
(6275188, 926190, 30454, '<td valign="top">Excellent colors, great capture. Good luck.</td>', 'Excellent colors, great capture. Good luck.', '2011-01-07 17:00:39.000000', NULL, 1),
(6275189, 926910, 30454, '<td valign="top">Nice capture and a funny title. Good luck.</td>', 'Nice capture and a funny title. Good luck.', '2011-01-07 17:01:39.000000', NULL, 1),
(6275190, 924050, 30454, '<td valign="top">Nice underwater photo. Good luck.</td>', 'Nice underwater photo. Good luck.', '2011-01-07 17:03:18.000000', NULL, 1),
(6275191, 926263, 30454, '<td valign="top">Great composition and nice tones.</td>', 'Great composition and nice tones.', '2011-01-07 17:03:47.000000', NULL, 1),
(6275192, 927148, 30454, '<td valign="top">I like the simplicity in this shot. Great tones.</td>', 'I like the simplicity in this shot. Great tones.', '2011-01-07 17:04:17.000000', NULL, 1),
