(6275219, 926069, 120171, '<td valign="top">This is one of my favourites in the challenge as the clarity of the shot and sharpness of the eyes are striking. My only negative observation is there are a few white specks on the black background, im only pointing them out as that is the one minus i can find. I hope you get a top ten.</td>', 'This is one of my favourites in the challenge as the clarity of the shot and sharpness of the eyes are striking. My only negative observation is there are a few white specks on the black background, im only pointing them out as that is the one minus i can find. I hope you get a top ten.', '2011-01-07 17:29:03.000000', NULL, 1),
(6275229, 927426, 76335, '<td valign="top">Good strong black and white landscape. I love the unexpected title.</td>', 'Good strong black and white landscape. I love the unexpected title.', '2011-01-07 17:33:21.000000', NULL, 1),
(6275231, 926833, 120171, '<td valign="top">Good B&amp;W image, spent quite a while looking at this one.</td>', 'Good B&W image, spent quite a while looking at this one.', '2011-01-07 17:33:28.000000', NULL, 1),
