(6275235, 927104, 120171, '<td valign="top">V. Cool</td>', 'V. Cool', '2011-01-07 17:37:39.000000', NULL, 1),
(6275236, 927265, 120171, '<td valign="top">Strangely cool. Love the clouds and the triangulation between the moon and the lamps.</td>', 'Strangely cool. Love the clouds and the triangulation between the moon and the lamps.', '2011-01-07 17:38:32.000000', NULL, 1),
(6275239, 926910, 120171, '<td valign="top">Great title and expressions.</td>', 'Great title and expressions.', '2011-01-07 17:40:21.000000', NULL, 1),
(6275244, 927337, 120171, '<td valign="top">I love the colours and detail in the rocks, but the out of focus rock at the foot of the image is in my opinion distracting, im sure you have a reason behind it but its not for me.</td>', 'I love the colours and detail in the rocks, but the out of focus rock at the foot of the image is in my opinion distracting, im sure you have a reason behind it but its not for me.', '2011-01-07 17:49:26.000000', NULL, 1),
(6275246, 927062, 59796, '<td valign="top">A haunting stare that''s memorable. Feels like a very good journalism pic. I find the color actually distracting a little bit - would''ve probably been better in B/W. Hope this does well.</td>', 'A haunting stare that''s memorable. Feels like a very good journalism pic. I find the color actually distracting a little bit - would''ve probably been better in B/W. Hope this does well.', '2011-01-07 17:50:20.000000', NULL, 1),
(6275247, 927492, 120171, '<td valign="top">Love the expressions.</td>', 'Love the expressions.', '2011-01-07 17:50:41.000000', NULL, 1),
(6275249, 926868, 120171, '<td valign="top">Really like the image but i would prefer the snow to be pure white.</td>', 'Really like the image but i would prefer the snow to be pure white.', '2011-01-07 17:51:22.000000', NULL, 1),
(6275250, 927332, 59796, '<td valign="top">Razor sharp pic. Wonderful patterns and texture all around, and I find myself trying to avoid staring at that magnetic eye. Very nice capture.</td>', 'Razor sharp pic. Wonderful patterns and texture all around, and I find myself trying to avoid staring at that magnetic eye. Very nice capture.', '2011-01-07 17:51:49.000000', NULL, 1),
(6275254, 927097, 59796, '<td valign="top">Very cool! Simple and minimalistic. The eye has nowhere to go but to the center of the spiral.</td>', 'Very cool! Simple and minimalistic. The eye has nowhere to go but to the center of the spiral.', '2011-01-07 17:54:52.000000', NULL, 1),
(6275255, 927046, 120171, '<td valign="top">Really like the colours and how clear the reflection is. on a negative the top left appears to be blown though</td>', 'Really like the colours and how clear the reflection is. on a negative the top left appears to be blown though', '2011-01-07 17:55:31.000000', NULL, 1),
(6275257, 926850, 59796, '<td valign="top">Feels like a shot out of a scary movie. Melancholy woods and lighting. Very nice.</td>', 'Feels like a shot out of a scary movie. Melancholy woods and lighting. Very nice.', '2011-01-07 17:57:09.000000', NULL, 1),
(6275261, 927418, 59796, '<td valign="top">Feels like I should be seeing this shot in a newspaper or on TV. Although I doubt they would use the same title (funny as it is:) Hope nature calms down and lets those people rebuild their normal lives.</td>', 'Feels like I should be seeing this shot in a newspaper or on TV. Although I doubt they would use the same title (funny as it is:) Hope nature calms down and lets those people rebuild their normal lives.', '2011-01-07 18:00:03.000000', NULL, 1),
(6275262, 924256, 120171, '<td valign="top">Works well, even if it does mess with my eyes.</td>', 'Works well, even if it does mess with my eyes.', '2011-01-07 18:00:27.000000', NULL, 1),
(6275269, 926735, 59796, '<td valign="top">Somehow, the title seems way too appropriate :)<br/>The diffused lighting and a good conversion to B/W make it perfect. The wonderful bokeh of the snow flakes in both the foreground and the background add to the charm. Very nicely done.</td>', 'Somehow, the title seems way too appropriate :)The diffused lighting and a good conversion to B/W make it perfect. The wonderful bokeh of the snow flakes in both the foreground and the background add to the charm. Very nicely done.', '2011-01-07 18:06:43.000000', NULL, 1),
(6275276, 927450, 59796, '<td valign="top">Wonderful low key capture. The stare, and the pose are fantastic! Although it makes me wonder what happened to her left leg :) Nicely done.</td>', 'Wonderful low key capture. The stare, and the pose are fantastic! Although it makes me wonder what happened to her left leg :) Nicely done.', '2011-01-07 18:11:01.000000', NULL, 1),
(6275285, 927338, 59796, '<td valign="top">A wonderful low-key capture that brings out the sadness in the person. Do you happen to have a pic of the person staring at the camera with the same expression? That might''ve made the sadness drip out of the pic I think :)</td>', 'A wonderful low-key capture that brings out the sadness in the person. Do you happen to have a pic of the person staring at the camera with the same expression? That might''ve made the sadness drip out of the pic I think :)', '2011-01-07 18:14:46.000000', NULL, 1),
(6275289, 926445, 59796, '<td valign="top">Almost looks like an Alligator from the thumbnail. Nice contrasting color combination, and fantastic droplets and refractions. Nicely done.</td>', 'Almost looks like an Alligator from the thumbnail. Nice contrasting color combination, and fantastic droplets and refractions. Nicely done.', '2011-01-07 18:15:46.000000', NULL, 1),
(6275291, 927486, 63218, '<td valign="top">Yummy light, great color. Flower dancers doing warm-up exercises on the floor. The perfect illustration of eye candy.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=831779" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg"/></a> <br/>Please accept this Gilded Lily as a mark of this flower photographer''s appreciation.</td>', 'Yummy light, great color. Flower dancers doing warm-up exercises on the floor. The perfect illustration of eye candy. Please accept this Gilded Lily as a mark of this flower photographer''s appreciation.', '2011-01-07 18:16:45.000000', NULL, 1),
(6275309, 927186, 76335, '<td valign="top">I like the tilt -- adds some humor to the subject. The vignette -- not so much.</td>', 'I like the tilt -- adds some humor to the subject. The vignette -- not so much.', '2011-01-07 18:24:59.000000', NULL, 1),
(6275312, 927412, 63218, '<td valign="top">Poetic DOF. Good work!</td>', 'Poetic DOF. Good work!', '2011-01-07 18:26:12.000000', NULL, 1),
(6275338, 924390, 120171, '<td valign="top">Too centred for my liking.</td>', 'Too centred for my liking.', '2011-01-07 18:51:31.000000', NULL, 1),
(6275340, 925348, 120171, '<td valign="top">Lovely image i just dont like the purple snow.</td>', 'Lovely image i just dont like the purple snow.', '2011-01-07 18:52:01.000000', NULL, 1),
(6275341, 926608, 120171, '<td valign="top">Too centred for my liking.</td>', 'Too centred for my liking.', '2011-01-07 18:53:00.000000', NULL, 1),
(6275343, 927241, 120171, '<td valign="top">Like the image but the white of the water looks blown out.</td>', 'Like the image but the white of the water looks blown out.', '2011-01-07 18:54:04.000000', NULL, 1),
(6275344, 926633, 120171, '<td valign="top">I like the dof and the lighting but the flowers are distracting from what your title would otherwise draw your eye to.</td>', 'I like the dof and the lighting but the flowers are distracting from what your title would otherwise draw your eye to.', '2011-01-07 18:54:51.000000', NULL, 1),
(6275346, 927418, 120171, '<td valign="top">Great title and humour to a sad situation.</td>', 'Great title and humour to a sad situation.', '2011-01-07 18:56:04.000000', NULL, 1),
(6275348, 927324, 120171, '<td valign="top">Of what?<br/> <br/>I see a cow. Certainly made me study the image.</td>', 'Of what? I see a cow. Certainly made me study the image.', '2011-01-07 18:57:00.000000', NULL, 1),
(6275350, 927439, 120171, '<td valign="top">The cup is so distracting.</td>', 'The cup is so distracting.', '2011-01-07 18:57:25.000000', NULL, 1),
(6275351, 927086, 120171, '<td valign="top">A little too soft for my liking.</td>', 'A little too soft for my liking.', '2011-01-07 18:58:42.000000', NULL, 1),
