(6275354, 926720, 120171, '<td valign="top">I like the fact that the angle is from above but on the negative side you cant really appreciate how high the cat is jumping.</td>', 'I like the fact that the angle is from above but on the negative side you cant really appreciate how high the cat is jumping.', '2011-01-07 18:59:08.000000', NULL, 1),
(6275356, 926627, 120171, '<td valign="top">The image appears a little dull (lighting)</td>', 'The image appears a little dull (lighting)', '2011-01-07 18:59:16.000000', NULL, 1),
