INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6275360, 926266, 120171, '<td valign="top">I think the moon being a lot larger within the shot would help to add impact, it just seems lost up there.</td>', 'I think the moon being a lot larger within the shot would help to add impact, it just seems lost up there.', '2011-01-07 18:59:48.000000', NULL, 1),
(6275361, 926160, 120171, '<td valign="top">There doesn''t seem to be any definition in the image, the object on the right is difficult to make out what it is.</td>', 'There doesn''t seem to be any definition in the image, the object on the right is difficult to make out what it is.', '2011-01-07 19:00:14.000000', NULL, 1),
(6275362, 927381, 120171, '<td valign="top">The image is suffering probably due to the lighting. i would like to see the crop to be taken up from the bottom to just before the cross so the congregation cant be seen.</td>', 'The image is suffering probably due to the lighting. i would like to see the crop to be taken up from the bottom to just before the cross so the congregation cant be seen.', '2011-01-07 19:00:18.000000', NULL, 1),
(6275363, 927210, 120171, '<td valign="top">The image appears a bit on the muddy side, i would like to see the snow pure white as this would in my opinion really improve this shot.</td>', 'The image appears a bit on the muddy side, i would like to see the snow pure white as this would in my opinion really improve this shot.', '2011-01-07 19:00:23.000000', NULL, 1),
(6275364, 926427, 120171, '<td valign="top">I like the title but the lights on the pole give away the camera shake and catch my eye too much.</td>', 'I like the title but the lights on the pole give away the camera shake and catch my eye too much.', '2011-01-07 19:00:29.000000', NULL, 1),
(6275412, 926633, 2158, '<td valign="top">The selective desaturation doesn''t work for me here.  I''m not sure why you''re trying to draw attention to the out-of-focus flowers.</td>', 'The selective desaturation doesn''t work for me here.  I''m not sure why you''re trying to draw attention to the out-of-focus flowers.', '2011-01-07 19:40:05.000000', NULL, 1),
(6275418, 926850, 76335, '<td valign="top">Beautiful sweeping vertical energy -- seems your subject has been shaken up by those vibes.</td>', 'Beautiful sweeping vertical energy -- seems your subject has been shaken up by those vibes.', '2011-01-07 19:51:21.000000', NULL, 1),
(6275420, 927006, 76335, '<td valign="top">The telephoto view really dwarfs that mountain.</td>', 'The telephoto view really dwarfs that mountain.', '2011-01-07 19:52:11.000000', NULL, 1),
(6275422, 927190, 76335, '<td valign="top">All three of you have had too much beer.</td>', 'All three of you have had too much beer.', '2011-01-07 19:53:38.000000', NULL, 1),
