(6275481, 927319, 73056, '<td valign="top">One of my favorites! Beautiful processing.</td>', 'One of my favorites! Beautiful processing.', '2011-01-07 21:04:25.000000', NULL, 1),
(6275482, 926425, 73056, '<td valign="top">Beautiful! This is one of my favorites.</td>', 'Beautiful! This is one of my favorites.', '2011-01-07 21:04:29.000000', NULL, 1),
(6275483, 926226, 73056, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2011-01-07 21:04:32.000000', NULL, 1),
(6275484, 926865, 73056, '<td valign="top">Great shot!</td>', 'Great shot!', '2011-01-07 21:04:35.000000', NULL, 1),
(6275486, 926868, 73056, '<td valign="top">Lovely!</td>', 'Lovely!', '2011-01-07 21:04:40.000000', NULL, 1),
