(6275489, 926441, 76335, '<td valign="top">I don''t like the smoothness of the textures, but I do like the transitional moment you''ve captured. The planetary motion is very evident here.</td>', 'I don''t like the smoothness of the textures, but I do like the transitional moment you''ve captured. The planetary motion is very evident here.', '2011-01-07 21:05:06.000000', NULL, 1),
(6275491, 927335, 76335, '<td valign="top">She''s a pretty girl, but the shadows are very unflattering.</td>', 'She''s a pretty girl, but the shadows are very unflattering.', '2011-01-07 21:05:40.000000', NULL, 1),
(6275493, 926425, 76335, '<td valign="top">Beautiful the way the reflection makes the clouds appear to blossom.</td>', 'Beautiful the way the reflection makes the clouds appear to blossom.', '2011-01-07 21:07:09.000000', NULL, 1),
(6275495, 926445, 76335, '<td valign="top">Orange and green are a delightful combination. And this is beautifully composed.</td>', 'Orange and green are a delightful combination. And this is beautifully composed.', '2011-01-07 21:07:46.000000', NULL, 1),
(6275498, 925431, 76335, '<td valign="top">I do like the pie-in-the-eye reflection in his glasses.</td>', 'I do like the pie-in-the-eye reflection in his glasses.', '2011-01-07 21:09:15.000000', NULL, 1),
(6275505, 925993, 76335, '<td valign="top">The lighting is beautiful. That wisp of hair, like a fanciful brushstroke, is a touch of genius.</td>', 'The lighting is beautiful. That wisp of hair, like a fanciful brushstroke, is a touch of genius.', '2011-01-07 21:12:55.000000', NULL, 1),
(6275506, 924791, 76335, '<td valign="top">As beautiful as it is bizarre -- not unlike that moment in a dream where things suddenly turn surreal.</td>', 'As beautiful as it is bizarre -- not unlike that moment in a dream where things suddenly turn surreal.', '2011-01-07 21:14:19.000000', NULL, 1),
(6275508, 926715, 30454, '<td valign="top">I see red too. Why only 643 pixels while 800 allowed? little harsh lighting may be due to direct flash. Goos depth of field.</td>', 'I see red too. Why only 643 pixels while 800 allowed? little harsh lighting may be due to direct flash. Goos depth of field.', '2011-01-07 21:17:16.000000', NULL, 1),
(6275510, 926287, 76335, '<td valign="top">The bokeh is nice. The figure''s face could be sharper.</td>', 'The bokeh is nice. The figure''s face could be sharper.', '2011-01-07 21:18:21.000000', NULL, 1),
