(6275552, 927120, 76335, '<td valign="top">It''s the Christmas hangover. Or maybe he just didn''t like what was being served. Good candid.</td>', 'It''s the Christmas hangover. Or maybe he just didn''t like what was being served. Good candid.', '2011-01-07 21:33:32.000000', NULL, 1),
(6275555, 926198, 76335, '<td valign="top">I like how the black stream cuts through all that white. Great use of black and white.</td>', 'I like how the black stream cuts through all that white. Great use of black and white.', '2011-01-07 21:34:46.000000', NULL, 1),
(6275565, 927403, 76335, '<td valign="top">The quality is rough. Blown highlights, missed focus... But with an image as poignant as this, such matters seem trivial. In fact, I''m not sure I''d have it any other way. A top pick from me.</td>', 'The quality is rough. Blown highlights, missed focus... But with an image as poignant as this, such matters seem trivial. In fact, I''m not sure I''d have it any other way. A top pick from me.', '2011-01-07 21:41:38.000000', NULL, 1),
(6275577, 926247, 76335, '<td valign="top">The greenish tones, the swirling rhythm -- and it''s a zebra (!). I''d love to read that this was shot in the wild. A nine for you.</td>', 'The greenish tones, the swirling rhythm -- and it''s a zebra (!). I''d love to read that this was shot in the wild. A nine for you.', '2011-01-07 21:49:26.000000', NULL, 1),
(6275578, 927127, 76335, '<td valign="top">Simply beautiful.</td>', 'Simply beautiful.', '2011-01-07 21:50:08.000000', NULL, 1),
(6275580, 924050, 76335, '<td valign="top">Simply remarkable. An image worthy of escape...</td>', 'Simply remarkable. An image worthy of escape...', '2011-01-07 21:50:57.000000', NULL, 1),
(6275581, 924050, 64086, '<td valign="top">Amazing shot, the reflection, the soft rays of light, the feeling of suspension, the murky bottom and the composition that has such a dynamic off-kilter feel.</td>', 'Amazing shot, the reflection, the soft rays of light, the feeling of suspension, the murky bottom and the composition that has such a dynamic off-kilter feel.', '2011-01-07 21:50:57.000000', NULL, 1),
(6275582, 926868, 64086, '<td valign="top">Wonderful haze. Beautiful photo.</td>', 'Wonderful haze. Beautiful photo.', '2011-01-07 21:51:52.000000', NULL, 1),
(6275587, 927486, 76335, '<td valign="top">They dance. Nicely composed.</td>', 'They dance. Nicely composed.', '2011-01-07 21:54:47.000000', NULL, 1),
(6275588, 927250, 76335, '<td valign="top">Who says a still life can''t have drama?</td>', 'Who says a still life can''t have drama?', '2011-01-07 21:54:48.000000', NULL, 1),
(6275589, 926263, 76335, '<td valign="top">A composition stunning in its simplicity.</td>', 'A composition stunning in its simplicity.', '2011-01-07 21:54:52.000000', NULL, 1),
