(6275592, 926547, 76335, '<td valign="top">Simple study in forms, light, textures. Very nice.</td>', 'Simple study in forms, light, textures. Very nice.', '2011-01-07 21:55:00.000000', NULL, 1),
(6275593, 925993, 64086, '<td valign="top">Beautiful portrait. The blue material and the shadows adds an unusual touch that really makes this photo stand out.</td>', 'Beautiful portrait. The blue material and the shadows adds an unusual touch that really makes this photo stand out.', '2011-01-07 21:55:01.000000', NULL, 1),
(6275594, 927371, 76335, '<td valign="top">Beautifully composed, tree against rock. Nice muted tones. No fancy Photoshop footwork. Commendable.</td>', 'Beautifully composed, tree against rock. Nice muted tones. No fancy Photoshop footwork. Commendable.', '2011-01-07 21:55:02.000000', NULL, 1),
