(6275596, 927146, 76335, '<td valign="top">I like the simple forms here, the excerpt of frozen rhythm snagged from the cold outdoors.</td>', 'I like the simple forms here, the excerpt of frozen rhythm snagged from the cold outdoors.', '2011-01-07 21:55:08.000000', NULL, 1),
(6275597, 927417, 76335, '<td valign="top">Good, initimate portrait. The eyes and simple smile really cut through the weathered features.</td>', 'Good, initimate portrait. The eyes and simple smile really cut through the weathered features.', '2011-01-07 21:55:16.000000', NULL, 1),
(6275598, 926858, 76335, '<td valign="top">Beyond cute.</td>', 'Beyond cute.', '2011-01-07 21:55:19.000000', NULL, 1),
