INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6276329, 924940, 96751, '<td valign="top">Oh Timfy, I''m so sorry for your loss.  December was not kind to DPC kitties.  Very emotional image.</td>', 'Oh Timfy, I''m so sorry for your loss.  December was not kind to DPC kitties.  Very emotional image.', '2011-01-08 11:31:30.000000', NULL, 0),
(6276332, 927459, 30861, '<td valign="top">I was very disappointed this did not ribbon, but I guess all in all it did very well, for being so non-plastic :-) I was one of your 10''s. Fabulous shot, great processing.</td>', 'I was very disappointed this did not ribbon, but I guess all in all it did very well, for being so non-plastic :-) I was one of your 10''s. Fabulous shot, great processing.', '2011-01-08 11:32:02.000000', NULL, 0),
(6276333, 927148, 96751, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Melethia:</b></div><hr/><i> I spy Catalina. </i></td></tr></table> <br/> <br/>LOL!  I guess I missed this one, Ben.  Beautiful tones.  I especially love the slightly brighter spot of sand in the front.</td>', 'Originally posted by Melethia: I spy Catalina.   LOL!  I guess I missed this one, Ben.  Beautiful tones.  I especially love the slightly brighter spot of sand in the front.', '2011-01-08 11:35:53.000000', NULL, 0),
(6276334, 927492, 30861, '<td valign="top">Lovely finish for what, in the end, is just a bunch of dumb-azz sheeps :-) I gave you a 9... For me, the texture of the coats was compelling.<br/> <br/>I believe I might have cropped this vertically to the upper right, so no legs showing and left edge was the edge of the wood upright, but that''s a different picture.<br/> <br/>Either way it''s a great shot for me, I don''t give out many 9''s or 10''s.</td>', 'Lovely finish for what, in the end, is just a bunch of dumb-azz sheeps :-) I gave you a 9... For me, the texture of the coats was compelling. I believe I might have cropped this vertically to the upper right, so no legs showing and left edge was the edge of the wood upright, but that''s a different picture. Either way it''s a great shot for me, I don''t give out many 9''s or 10''s.', '2011-01-08 11:36:38.000000', NULL, 0),
(6276337, 927492, 96751, '<td valign="top">Congrats on making the PH gallery.  LOVE this shot.  "WhatCHOO lookin'' at???"</td>', 'Congrats on making the PH gallery.  LOVE this shot.  "WhatCHOO lookin'' at???"', '2011-01-08 11:40:32.000000', NULL, 0),
